import{_ as t,c as s,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"《伊川易傳》簡介","description":"伊川易傳 - 《伊川易傳》簡介","frontmatter":{"title":"《伊川易傳》簡介","description":"伊川易傳 - 《伊川易傳》簡介"},"headers":[],"relativePath":"classics/yichuan/001.md","filePath":"classics/yichuan/001.md"}'),r={name:"classics/yichuan/001.md"};function c(i,a,o,p,d,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《伊川易傳》簡介",tabindex:"-1"},[l("《伊川易傳》簡介 "),e("a",{class:"header-anchor",href:"#《伊川易傳》簡介","aria-label":"Permalink to “《伊川易傳》簡介”"},"​")],-1),e("p",null,"《伊川易傳》是中國北宋時期著名哲學家、理學家程頤註解《周易》的哲學著作，也被稱為《周易程氏傳》或《程氏易傳》。這部作品共4卷，大約15萬字，由程頤在涪陵寫成，成書於宋哲宗元符二年（1099年），當時程頤66歲。程頤在《易傳序》中提出了“體用一源，顯微無間”的理學命題，強調無形的理寓於有形的象中，理與象即是理與事的體用關係。",-1),e("p",null,"程頤在《伊川易傳》中，借解釋《周易》卦辭爻象來闡明義理，易象反映天地萬物之物象，易理則概括了天地之理。他認為理不僅是天地萬物的根本，也是社會等級、人生道德的由來，書中還包括了陰陽、動靜變化的思想和關於理欲的觀點，反映了程頤從宇宙自然到社會人生的較系統的哲學思想。",-1),e("p",null,"《伊川易傳》從元代開始被列為科舉必讀書，其哲學思想在封建社會後期有過重大影響。程頤的這部作品不僅對《易經》的解釋有獨到之處，而且集中體現了他的理學思想，是程頤平生用力最多的著作。",-1),e("p",null,"程頤的《易傳》在成書後，由於程頤本人對這部書非常重視，他去世後傳本不一，楊時曾加編次。但在宋元時，其書編卷仍不一致。清康熙間呂留良定為4卷，匯入《二程全書》，後塗宗瀛又作校訂。",-1),e("p",null,"《伊川易傳》作為程頤理學思想的主幹，是程朱學派的理學經典著作之一，其地位與朱熹的《四書集註》同樣重要。程頤的這部著作對後世產生了深遠的影響，成為宋明理學的重要著作。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
